/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// </summary>
[ExtensionOf(tableStr(GUPPricingRule))]
final class METGUPPricingRuleTbl_Extension
{
}

Method.Source:
/// <summary>
/// Refactor
/// </summary>
/// <param name = "_refRecId">PricingRuleHeader or PricingRuleLine</param>
/// <returns>true if is OR attribute; otherwise, false.</returns>
static boolean metIsOrRule(GUPRefRecId _refRecId)
{
    GUPPricingRuleCondition ruleCondition;
    GUPPricingRule orRule;

    select firstonly RecId from orRule
            where orRule.RecId == _refRecId
               && orRule.PriceAttributeGroupName != ''
            exists join ruleCondition
            where ruleCondition.RuleId == orRule.RecId
               && ruleCondition.METisOR == NoYes::Yes;

    return (orRule.RecId != 0);
}
